import java.io.*;import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.commons.*;
public class RemapSrg {public static void main(String[] a)throws Exception {Map<String,String> map=new HashMap<>();for(String line:Files.readAllLines(Paths.get(a[2]))){String[] x=line.split(" ");if(x[0].equals("CL:"))map.put(x[1],x[2]);else if(x[0].equals("FD:")){int slash=x[1].lastIndexOf('/');map.put(x[1].substring(0,slash)+"."+x[1].substring(slash+1),x[2].substring(x[2].lastIndexOf('/')+1));}else if(x[0].equals("MD:")){int slash=x[1].lastIndexOf('/');map.put(x[1].substring(0,slash)+"."+x[1].substring(slash+1)+x[2],x[3].substring(x[3].lastIndexOf('/')+1));}}SimpleRemapper r=new SimpleRemapper(map);try(JarFile in=new JarFile(a[0]);JarOutputStream out=new JarOutputStream(new FileOutputStream(a[1]))){Set<String> seen=new HashSet<>();for(JarEntry e:Collections.list(in.entries())){if(e.isDirectory()||e.getName().startsWith("META-INF/"))continue;byte[] b=in.getInputStream(e).readAllBytes();String n=e.getName();if(n.endsWith(".class")){ClassWriter w=new ClassWriter(0);new ClassReader(b).accept(new ClassRemapper(w,r),0);b=w.toByteArray();n=r.mapType(n.substring(0,n.length()-6))+".class";}if(seen.add(n)){out.putNextEntry(new JarEntry(n));out.write(b);out.closeEntry();}}}}}
